-- Cash flow: received payments by payment day and freight/pot costs generated by orders created in the period.
create or replace function public.get_cash_flow(p_start date, p_end date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare result jsonb;
begin
  if p_start is null or p_end is null or p_start > p_end or p_end - p_start > 366 then
    raise exception 'Invalid period: start must not exceed end and the range is limited to 366 days';
  end if;
  with states as (
    select orders.*, snapshot.received_amount, snapshot.received_payment_status, snapshot.payment_platform,
      snapshot.field_versions,
      private.financial_payment_status(coalesce(snapshot.payment_status,orders.status_pagamento)) payment,
      snapshot.payment_status is not null has_versioned_payment,
      lower(btrim(coalesce(snapshot.shipping_status,orders.status_rastreio))) shipping
    from public.orders orders
    left join public.order_financial_snapshots snapshot on snapshot.order_id=orders.id
  ), payments as (
    select states.id order_id,
      coalesce(states.data_pagamento,((states.field_versions->'received_amount'->>'at')::timestamptz at time zone 'America/Sao_Paulo')::date) paid_date,
      states.data_pagamento is null estimated_date,
      states.seller_id, coalesce(sellers.name,'Não atribuído') seller_name,
      states.nome_cliente customer_name, states.payment_platform platform,
      states.status_pagamento payment_status, states.received_amount amount
    from states left join public.sellers sellers on sellers.id=states.seller_id
    where states.received_amount is not null and states.payment in ('paid','partial')
      and states.payment=states.received_payment_status
  ), created as (
    select states.*,
      coalesce(case when has_versioned_payment then payment='cancelado' else cancelado end,false)
        or coalesce(shipping='cancelado',false) cancelled
    from states
    where states.data >= p_start::timestamp at time zone 'America/Sao_Paulo'
      and states.data < (p_end + 1)::timestamp at time zone 'America/Sao_Paulo'
  ), generated as (
    select created.seller_id, coalesce(sellers.name,'Não atribuído') seller_name,
      count(*) filter (where not cancelled) freight_orders,
      coalesce(sum(product_units) filter (where not cancelled and shipping is distinct from 'devolvido'),0) units,
      count(*) filter (where not cancelled and shipping is distinct from 'devolvido' and product_units is null) missing_units
    from created left join public.sellers sellers on sellers.id=created.seller_id
    group by created.seller_id, sellers.name
  )
  select jsonb_build_object(
    'start',to_char(p_start,'YYYY-MM-DD'),'end',to_char(p_end,'YYYY-MM-DD'),
    'payments',coalesce((select jsonb_agg(to_jsonb(payments) order by paid_date,order_id) from payments
      where paid_date between p_start and p_end),'[]'::jsonb),
    'generated_costs',coalesce((select jsonb_agg(jsonb_build_object('seller_id',seller_id,'seller_name',seller_name,
      'freight_orders',freight_orders,'units',units,'missing_units',missing_units,
      'shipping_cost',freight_orders*30.00,'production_cost',units*6.90) order by seller_name,seller_id) from generated),'[]'::jsonb),
    'rates',jsonb_build_object('production',6.90,'shipping',30.00)
  ) into result;
  return result;
end;
$$;
revoke all on function public.get_cash_flow(date,date) from public, anon;
grant execute on function public.get_cash_flow(date,date) to authenticated;
notify pgrst, 'reload schema';
